<script setup lang="ts">
import { onMounted, ref, watch } from 'vue'
import PaginationBar from '../../campus-shared/PaginationBar.vue'
import * as api from './api'
const filterStatus = ref('PENDING')
const tab = ref('posts'), page = ref(1), total = ref(0), busy = ref(false), message = ref(''), reason = ref('')
const reviews = ref<api.Review[]>([]), comments = ref<api.Comment[]>([]), reports = ref<api.Report[]>([]), selected = ref<api.Review | null>(null), inspected = ref<api.Post | null>(null), images = ref<api.ImageTicket[]>([])
async function load(target = 1) { busy.value = true; message.value = ''; selected.value = null; inspected.value = null; images.value = []; try { page.value = target; if (tab.value === 'posts') { const result = await api.reviewQueue(target, filterStatus.value); reviews.value = result.items; total.value = result.total } else if (tab.value === 'comments') { const result = await api.commentQueue(target, filterStatus.value); comments.value = result.items; total.value = result.total } else { const result = await api.reports(target, filterStatus.value); reports.value = result.items; total.value = result.total } } catch (e) { message.value = e instanceof Error ? e.message : '队列加载失败' } finally { busy.value = false } }
async function decision(status: string) { if (!selected.value || !reason.value.trim()) return; busy.value = true; try { await api.decide(selected.value.id, status, reason.value); reason.value = ''; await load(page.value); message.value = '帖子审核决定已保存。' } catch (e) { message.value = e instanceof Error ? e.message : '审核失败' } finally { busy.value = false } }
async function comment(c: api.Comment, status: string) { if (!reason.value.trim()) { message.value = '请先填写处理原因。'; return }; busy.value = true; try { await api.moderateComment(c, status, reason.value); await load(page.value); reason.value = ''; message.value = '评论处理已保存。' } catch (e) { message.value = e instanceof Error ? e.message : '处理失败' } finally { busy.value = false } }
async function inspect(r: api.Report) { busy.value = true; images.value = []; try { inspected.value = await api.detail(r.postId) } catch (e) { message.value = e instanceof Error ? e.message : '帖子已不可公开读取' } finally { busy.value = false } }
async function hide() { if (!inspected.value || !reason.value.trim()) return; busy.value = true; try { await api.hide(inspected.value.id, inspected.value.version, reason.value); inspected.value = null; message.value = '帖子已隐藏，公开页面和搜索将停止展示。' } catch (e) { message.value = e instanceof Error ? e.message : '隐藏失败' } finally { busy.value = false } }
async function resolve(r: api.Report, status: string) { if (!reason.value.trim()) { message.value = '请先填写处理结论。'; return }; busy.value = true; try { await api.resolve(r, status, reason.value); await load(page.value); reason.value = ''; message.value = '举报处理结论已保存。' } catch (e) { message.value = e instanceof Error ? e.message : '处理失败' } finally { busy.value = false } }
async function viewImages(id: string) { busy.value = true; try { images.value = await api.imageTickets(id) } catch (e) { message.value = e instanceof Error ? e.message : '图片服务不可用' } finally { busy.value = false } }
watch(tab, () => { filterStatus.value = tab.value === 'reports' ? 'OPEN' : 'PENDING'; void load() }); onMounted(() => load())
</script>
<template><section><div class="section-heading"><h1>社区内容审核</h1><button class="secondary" :disabled="busy" @click="load(page)">刷新队列</button></div><label for="communityQueue">处理队列</label><select id="communityQueue" v-model="tab" :disabled="busy"><option value="posts">待审帖子</option><option value="comments">待审评论</option><option value="reports">待处理举报</option></select><label for="communityStatus">处理状态</label><select id="communityStatus" v-model="filterStatus" :disabled="busy" @change="load()"><option v-for="s in (tab === 'reports' ? ['OPEN','RESOLVED','DISMISSED'] : tab === 'comments' ? ['PENDING','APPROVED','REJECTED','HIDDEN'] : ['PENDING','APPROVED','REJECTED'])" :key="s" :value="s">{{ api.states[s] }}</option></select><label for="communityModerationReason">处理原因 / 结论</label><textarea id="communityModerationReason" v-model.trim="reason" maxlength="500" rows="2" :disabled="busy" /><p v-if="message" role="status">{{ message }}</p>
  <template v-if="tab === 'posts'"><article v-for="r in reviews" :key="r.id" class="workspace-card"><h2>{{ r.snapshot.title }}</h2><p class="post-body">{{ r.snapshot.body }}</p><button class="secondary" :disabled="busy" @click="selected = r">选择审核此帖</button></article><article v-if="selected && selected.status === 'PENDING'" class="workspace-card"><h2>正在审核：{{ selected.snapshot.title }}</h2><p>内容版本 {{ selected.contentVersion }} · 图片 {{ selected.snapshot.imageIds.length }} 张</p><div class="button-row"><button :disabled="busy || !reason" @click="decision('APPROVED')">通过并公开帖子</button><button class="secondary" :disabled="busy || !reason" @click="decision('REJECTED')">驳回帖子</button><button v-if="selected.snapshot.imageIds.length" class="secondary" :disabled="busy" @click="viewImages(selected.postId)">查看待审图片</button></div></article></template>
  <template v-else-if="tab === 'comments'"><article v-for="c in comments" :key="c.id" class="workspace-card"><p class="post-body">{{ c.body }}</p><p>帖子 {{ c.postId }} · {{ api.states[c.status] }}</p><div class="button-row"><button v-if="['PENDING','REJECTED'].includes(c.status)" :disabled="busy" @click="comment(c, 'APPROVED')">通过评论</button><button v-if="c.status === 'PENDING'" class="secondary" :disabled="busy" @click="comment(c, 'REJECTED')">驳回评论</button><button v-if="c.status === 'APPROVED'" class="secondary" :disabled="busy" @click="comment(c, 'HIDDEN')">隐藏评论</button></div></article></template>
  <template v-else><article v-for="r in reports" :key="r.id" class="workspace-card"><h2>举报 {{ r.id }} · 帖子 {{ r.postId }}</h2><p>{{ r.reason }}</p><div class="button-row"><button class="secondary" :disabled="busy" @click="inspect(r)">查看被举报帖子</button><button v-if="r.status === 'OPEN'" :disabled="busy" @click="resolve(r, 'RESOLVED')">登记已处理</button><button v-if="r.status === 'OPEN'" class="secondary" :disabled="busy" @click="resolve(r, 'DISMISSED')">驳回举报</button></div></article><article v-if="inspected" class="workspace-card"><h2>{{ inspected.title }}</h2><p class="post-body">{{ inspected.body }}</p><button :disabled="busy || !reason" @click="hide">隐藏违规帖子</button></article></template>
  <div class="post-images"><img v-for="image in images" :key="image.fileId" :src="image.url" alt="正在审核的探店图片" referrerpolicy="no-referrer" /></div><p v-if="!busy && !total">当前队列暂无待处理内容。</p><PaginationBar :page="page" :size="20" :total="total" :disabled="busy" @change="load" />
</section></template>
